import { defineChannel, POST } from "@grok/agent-sdk/channels";
import { z } from "zod";
import { formatQueuePrompt, parseQueueEvent } from "../lib/parse-queue-event.js";

export default defineChannel({
  routes: [
    POST("/issue", {
      description: "Triage an existing tracker issue",
      bodySchema: z.unknown(),
      handler: async (_req, route) => {
        const parsed = parseQueueEvent(route.body);
        if (!parsed.ok) {
          if ("ignored" in parsed) {
            return new Response(null, { status: 202 });
          }
          return new Response(null, { status: 400 });
        }
        route.waitUntil(
          route.send(formatQueuePrompt(parsed.issue), {
            continuationToken: parsed.issue.identifier,
            admission: "coalesce",
            title: parsed.issue.title === "" ? undefined : parsed.issue.title,
          }),
        );
        return new Response(null, { status: 202 });
      },
    }),
  ],
});
